pid /tmp/nginx.pid;
events { worker_connections 1024; }
http {
  log_format cache '$remote_addr "$request" $status $body_bytes_sent $request_time cache=$upstream_cache_status';
  access_log /dev/stdout cache;
  error_log /dev/stderr warn;
  # 7d: tool descriptions are stable.
  proxy_cache_path /var/cache/nginx/embeddings levels=1:2 keys_zone=embeddings:16m max_size=1g inactive=7d use_temp_path=off;
  # $request_body is empty once a body spills past client_body_buffer_size; such a
  # request must bypass the cache, or every large body would share one key.
  map $request_body $skip_cache { "" 1; default 0; }
  server {
    listen 8080;
    client_max_body_size 16m;
    client_body_buffer_size 16m;
    location / {
      proxy_pass http://embeddinggemma-2.ai.svc.cluster.local:8080;
      # embeddinggemma-2's 194-item batch is ~7.4s; toolhive gives up at 120s.
      proxy_read_timeout 600s;
      proxy_cache embeddings;
      proxy_cache_methods POST;
      proxy_cache_key "$request_uri|$request_body";
      proxy_cache_valid 200 7d;
      # The key is stored in the cache file header, which must fit proxy_buffer_size: at the
      # 4k default ~40% of embedding requests failed "cache key too large" and bypassed.
      proxy_buffer_size 64k;
      proxy_buffers 4 64k;
      proxy_busy_buffers_size 64k;
      proxy_cache_bypass $skip_cache;
      proxy_no_cache $skip_cache;
      # MCP sessions initializing together on a cold cache send the same 194-item
      # batch; one goes upstream, the rest wait for it. Past one cold batch (~35s).
      proxy_cache_lock on;
      proxy_cache_lock_timeout 60s;
      # Surfaced as the cache_status metric label (agentgateway-metrics policy).
      add_header X-Cache-Status $upstream_cache_status always;
    }
  }
}

config_file=/opt/printer_data/config/moonraker-obico.cfg
token="`awk '
  /^\[server\]/ { in_server=1; next }
  /^\[/ { in_server=0 }
  in_server {
    line=$0
    sub(/^[[:space:]]*/, "", line)
    if (line ~ /^auth_token[[:space:]]*=/) {
      sub(/^auth_token[[:space:]]*=[[:space:]]*/, "", line)
      print line
      exit
    }
  }
' "$config_file" 2>/dev/null || true`"

awk -v token="$token" '
  { print }
  /^\[server\]/ && token != "" && !done {
    print "auth_token = " token
    done=1
  }
' /config-template/moonraker-obico.cfg > "$config_file.tmp"
mv "$config_file.tmp" "$config_file"

if [ -n "$token" ]; then
  echo "Rendered config and preserved auth_token"
else
  echo "Rendered config without auth_token; run link flow"
fi
